import React from 'react';

interface MessageIconProps {
  size?: number;
  className?: string;
}

const MessageIcon: React.FC<MessageIconProps> = ({ size = 26, className = '' }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 32 32"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    style={{ overflow: 'visible' }}
  >
    <defs>
      <linearGradient id="msgGrad" x1="2" y1="6" x2="30" y2="28" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#38bdf8" />
        <stop offset="100%" stopColor="#3b82f6" />
      </linearGradient>
      <filter id="msgGlow" x="-20%" y="-20%" width="140%" height="140%">
        <feGaussianBlur stdDeviation="1.5" result="blur" />
        <feComposite in="SourceGraphic" in2="blur" operator="over" />
      </filter>
    </defs>

    <path
      d="M26.6667 5.33337H5.33333C3.86 5.33337 2.66667 6.52671 2.66667 8.00004V21.3334C2.66667 22.8067 3.86 24 5.33333 24H8.00001V28C8.00001 28.5334 8.66668 28.8 9.06668 28.4L13.3333 24H26.6667C28.14 24 29.3333 22.8067 29.3333 21.3334V8.00004C29.3333 6.52671 28.14 5.33337 26.6667 5.33337Z"
      fill="url(#msgGrad)"
      filter="url(#msgGlow)"
    />

    <circle cx="10" cy="14.6667" r="1.5" fill="white" />
    <circle cx="16" cy="14.6667" r="1.5" fill="white" />
    <circle cx="22" cy="14.6667" r="1.5" fill="white" />
  </svg>
);

export default MessageIcon;
